list_shipping_classes.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.shippingClasses().listShippingClasses(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("shipping_classes")) {
    Map<?, ?> shippingClass = (Map<?, ?>) row;
    System.out.println(shippingClass.get("id") + " " + shippingClass.get("name") + " " + shippingClass.get("is_default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

